Path('/app/internal/projection/projection.go').write_text('package projection\n\nimport (\n\t"crypto/sha256"\n\t"encoding/hex"\n\t"encoding/json"\n\t"os"\n\t"time"\n\n\t"baylock/internal/checkpoint"\n\t"baylock/internal/domain"\n\t"baylock/internal/journal"\n\t"baylock/internal/legacy"\n\t"baylock/internal/pol"\n)\n\ntype Snapshot struct {\n\tGeneratedFrom    string `json:"generated_from"`\n\tEventLineCount   int    `json:"event_line_count"`\n\tAppliedCount     int    `json:"applied_count"`\n\tRejectedCount    int    `json:"rejected_count"`\n\tProjectionDigest string `json:"projection_digest"`\n}\n\nfunc Rebuild() (*Snapshot, error) {\n\tlines, lineCount, malformed, err := journal.ReadAllEvents()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\t_ = malformed\n\tengine := pol.NewEngine()\n\tcp, err := checkpoint.Load()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tif err := legacy.ApplyIfNeeded(&cp.MigratedLegacy, engine); err != nil {\n\t\treturn nil, err\n\t}\n\tengine.ProcessLines(lines)\n\twatermark := engine.Watermark()\n\tif watermark.IsZero() {\n\t\twatermark = time.Unix(0, 0).UTC()\n\t}\n\tengine.ApplyGraceExpirations(watermark)\n\tif err := engine.PersistTallies(); err != nil {\n\t\treturn nil, err\n\t}\n\tsnap := &Snapshot{\n\t\tGeneratedFrom:  domain.GeneratedFrom,\n\t\tEventLineCount: lineCount,\n\t\tAppliedCount:   engine.AppliedCount,\n\t\tRejectedCount:  engine.RejectedCount,\n\t}\n\tbody, err := json.Marshal(canonicalBody(snap))\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tsum := sha256.Sum256(body)\n\tsnap.ProjectionDigest = hex.EncodeToString(sum[:])\n\tcp.JournalSeq = len(lines)\n\tcp.ProjectionDigest = snap.ProjectionDigest\n\tcp.RebuildAt = time.Now().UTC().Format(time.RFC3339)\n\tif err := checkpoint.Save(cp); err != nil {\n\t\treturn nil, err\n\t}\n\tif err := saveProjection(snap); err != nil {\n\t\treturn nil, err\n\t}\n\treturn snap, nil\n}\n\nfunc canonicalBody(snap *Snapshot) map[string]any {\n\treturn map[string]any{\n\t\t"generated_from":   snap.GeneratedFrom,\n\t\t"event_line_count": snap.EventLineCount,\n\t\t"applied_count":    snap.AppliedCount,\n\t\t"rejected_count":   snap.RejectedCount,\n\t}\n}\n\nfunc saveProjection(snap *Snapshot) error {\n\tdata, err := json.MarshalIndent(snap, "", "  ")\n\tif err != nil {\n\t\treturn err\n\t}\n\treturn os.WriteFile("/app/state/projection.json", data, 0o644)\n}\n\nfunc Load() (*Snapshot, error) {\n\tdata, err := os.ReadFile("/app/state/projection.json")\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tvar snap Snapshot\n\tif err := json.Unmarshal(data, &snap); err != nil {\n\t\treturn nil, err\n\t}\n\treturn &snap, nil\n}\n')
