Path('/app/internal/journal/journal.go').write_text('package journal\n\nimport (\n\t"crypto/sha256"\n\t"encoding/hex"\n\t"encoding/json"\n\t"os"\n\t"path/filepath"\n\t"strings"\n\n\t"baylock/internal/config"\n)\n\ntype BatchRecord struct {\n\tName         string `json:"name"`\n\tFile         string `json:"file"`\n\tEventCount   int    `json:"event_count"`\n\tDurableBytes int    `json:"durable_bytes"`\n}\n\ntype Manifest struct {\n\tBatches []BatchRecord `json:"batches"`\n}\n\nfunc ManifestPath() string {\n\treturn filepath.Join(config.JournalRoot, "manifest.json")\n}\n\nfunc BatchPath(name string) string {\n\treturn filepath.Join(config.JournalRoot, "batches", name+".jsonl")\n}\n\nfunc LoadManifest() (*Manifest, error) {\n\tdata, err := os.ReadFile(ManifestPath())\n\tif err != nil {\n\t\tif os.IsNotExist(err) {\n\t\t\treturn &Manifest{Batches: []BatchRecord{}}, nil\n\t\t}\n\t\treturn nil, err\n\t}\n\tvar m Manifest\n\tif err := json.Unmarshal(data, &m); err != nil {\n\t\treturn nil, err\n\t}\n\treturn &m, nil\n}\n\nfunc SaveManifest(m *Manifest) error {\n\tif err := os.MkdirAll(filepath.Join(config.JournalRoot, "batches"), 0o755); err != nil {\n\t\treturn err\n\t}\n\tdata, err := json.MarshalIndent(m, "", "  ")\n\tif err != nil {\n\t\treturn err\n\t}\n\treturn os.WriteFile(ManifestPath(), data, 0o644)\n}\n\nfunc ImportBatch(name, eventsPath string) (bool, error) {\n\tm, err := LoadManifest()\n\tif err != nil {\n\t\treturn false, err\n\t}\n\tfor _, b := range m.Batches {\n\t\tif b.Name == name {\n\t\t\treturn false, nil\n\t\t}\n\t}\n\tsrc, err := os.ReadFile(eventsPath)\n\tif err != nil {\n\t\treturn false, err\n\t}\n\tdst := BatchPath(name)\n\tif err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {\n\t\treturn false, err\n\t}\n\tif err := os.WriteFile(dst, src, 0o644); err != nil {\n\t\treturn false, err\n\t}\n\tdurable := durableLength(string(src))\n\tprefix := string(src)\n\tif durable <= len(src) {\n\t\tprefix = string(src[:durable])\n\t}\n\tlines := splitNonBlank(prefix)\n\trec := BatchRecord{\n\t\tName:         name,\n\t\tFile:         filepath.Base(dst),\n\t\tEventCount:   len(lines),\n\t\tDurableBytes: durable,\n\t}\n\tm.Batches = append(m.Batches, rec)\n\tif err := SaveManifest(m); err != nil {\n\t\treturn false, err\n\t}\n\treturn true, nil\n}\n\n// durableLength ends at the last complete newline so truncated tails are invisible.\nfunc durableLength(src string) int {\n\tif src == "" {\n\t\treturn 0\n\t}\n\tlast := strings.LastIndex(src, "\\n")\n\tif last < 0 {\n\t\treturn len(src)\n\t}\n\treturn last + 1\n}\n\nfunc EventCountForBytes(src string) int {\n\tdurable := durableLength(src)\n\tif durable <= len(src) {\n\t\tsrc = src[:durable]\n\t}\n\treturn len(splitNonBlank(src))\n}\n\nfunc splitNonBlank(src string) []string {\n\tvar out []string\n\tfor _, line := range strings.Split(src, "\\n") {\n\t\tif strings.TrimSpace(line) != "" {\n\t\t\tout = append(out, line)\n\t\t}\n\t}\n\treturn out\n}\n\nfunc ReadAllEvents() ([][]byte, int, int, error) {\n\tm, err := LoadManifest()\n\tif err != nil {\n\t\treturn nil, 0, 0, err\n\t}\n\tvar all [][]byte\n\tlineCount := 0\n\tmalformed := 0\n\tfor _, batch := range m.Batches {\n\t\tpath := filepath.Join(config.JournalRoot, "batches", batch.File)\n\t\tdata, err := os.ReadFile(path)\n\t\tif err != nil {\n\t\t\treturn nil, 0, 0, err\n\t\t}\n\t\tdurable := batch.DurableBytes\n\t\tif durable > len(data) {\n\t\t\tdurable = len(data)\n\t\t}\n\t\tchunk := string(data[:durable])\n\t\tfor _, line := range strings.Split(chunk, "\\n") {\n\t\t\tif strings.TrimSpace(line) == "" {\n\t\t\t\tlineCount++\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tlineCount++\n\t\t\tif json.Valid([]byte(line)) {\n\t\t\t\tall = append(all, []byte(line))\n\t\t\t} else {\n\t\t\t\tmalformed++\n\t\t\t}\n\t\t}\n\t}\n\treturn all, lineCount, malformed, nil\n}\n\nfunc ComputeJournalDigest() (string, error) {\n\tm, err := LoadManifest()\n\tif err != nil {\n\t\treturn "", err\n\t}\n\tdigest := sha256.New()\n\tfor _, batch := range m.Batches {\n\t\tpath := filepath.Join(config.JournalRoot, "batches", batch.File)\n\t\tdata, err := os.ReadFile(path)\n\t\tif err != nil {\n\t\t\treturn "", err\n\t\t}\n\t\tdurable := batch.DurableBytes\n\t\tif durable > len(data) {\n\t\t\tdurable = len(data)\n\t\t}\n\t\tchunk := string(data[:durable])\n\t\tfor _, line := range strings.Split(chunk, "\\n") {\n\t\t\tif strings.TrimSpace(line) == "" {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tif !json.Valid([]byte(line)) {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tdigest.Write([]byte(line))\n\t\t\tdigest.Write([]byte("\\n"))\n\t\t}\n\t}\n\treturn hex.EncodeToString(digest.Sum(nil)), nil\n}\n')
