Path('/app/internal/legacy/legacy.go').write_text('package legacy\n\nimport (\n\t"encoding/json"\n\t"os"\n\n\t"baylock/internal/config"\n\t"baylock/internal/domain"\n\t"baylock/internal/pol"\n)\n\ntype LegacyRow struct {\n\tPrincipal string `json:"principal"`\n\tFailures  int    `json:"failures"`\n\tLocked    bool   `json:"locked"`\n}\n\ntype LegacyFile struct {\n\tGeneratedFrom string      `json:"generated_from"`\n\tRows          []LegacyRow `json:"rows"`\n}\n\nfunc ApplyIfNeeded(migrated *bool, engine *pol.Engine) error {\n\tif *migrated {\n\t\treturn nil\n\t}\n\tdata, err := os.ReadFile(config.LegacyTallyFile)\n\tif err != nil {\n\t\tif os.IsNotExist(err) {\n\t\t\t*migrated = true\n\t\t\treturn nil\n\t\t}\n\t\treturn err\n\t}\n\tvar legacy LegacyFile\n\tif err := json.Unmarshal(data, &legacy); err != nil {\n\t\treturn err\n\t}\n\tfor _, row := range legacy.Rows {\n\t\tlocked := row.Locked || row.Failures >= domain.FailureLimit\n\t\tengine.SeedTally(row.Principal, row.Failures, locked)\n\t}\n\t*migrated = true\n\treturn nil\n}\n')
print('/app/internal/legacy/legacy.go')
Path('/app/internal/pol/engine.go').parent.mkdir(parents=True, exist_ok=True)
Path('/app/internal/pol/engine.go').write_text('package pol\n\nimport (\n\t"encoding/json"\n\t"sort"\n\t"strings"\n\t"time"\n\n\t"baylock/internal/domain"\n\t"baylock/internal/state"\n)\n\n// Event is a validated journal row applied by the engine.\ntype Event struct {\n\tEventID        string\n\tPrincipal      string\n\tOperation      string\n\tViewID         string\n\tLogicalTime    time.Time\n\tLogicalTimeStr string\n\tSeq            int\n\tSourceReplica  string\n\tTargetEventID  string\n\tExpiresAt      string\n\tAmount         *int\n\tEpoch          int\n\tLineIndex      int\n}\n\ntype PrincipalState struct {\n\tPrincipal          string\n\tFailures           int\n\tLocked             bool\n\tSuspended          bool\n\tSuspendedByReplica string\n\tEpoch              int\n\tLastEventID        string\n\tLastLogicalTime    string\n}\n\ntype Engine struct {\n\tPrincipals        map[string]*PrincipalState\n\tTallies           map[string]*domain.Tally\n\tSeenEventIDs      map[string]map[string]any\n\tApplied           map[string]*Event\n\tRejectedIDs       map[string]struct{}\n\tReversed          map[string]struct{}\n\tSeqHighwater      map[string]int\n\tGraceExpires      map[string]string\n\tCorrectionPrev    map[string]int\n\tActiveView        string\n\tActivePrincipal   string\n\tAppliedCount      int\n\tRejectedCount     int\n\tSkippedIdempotent int\n\tRejections        []domain.Rejection\n\tMaxLogicalTime    time.Time\n}\n\nfunc NewEngine() *Engine {\n\treturn &Engine{\n\t\tPrincipals:     map[string]*PrincipalState{},\n\t\tTallies:        map[string]*domain.Tally{},\n\t\tSeenEventIDs:   map[string]map[string]any{},\n\t\tApplied:        map[string]*Event{},\n\t\tRejectedIDs:    map[string]struct{}{},\n\t\tReversed:       map[string]struct{}{},\n\t\tSeqHighwater:   map[string]int{},\n\t\tGraceExpires:   map[string]string{},\n\t\tCorrectionPrev: map[string]int{},\n\t\tActiveView:     domain.ViewHost,\n\t}\n}\n\nfunc seqKey(principal, replica string) string {\n\treturn principal + "|" + replica\n}\n\ntype indexedEvent struct {\n\ttime      time.Time\n\teventID   string\n\tlineIndex int\n\tobj       map[string]any\n}\n\n// ProcessLines folds durable rows in ascending (logical_time, event_id, line_index).\nfunc (e *Engine) ProcessLines(lines [][]byte) {\n\tsortable := make([]indexedEvent, 0, len(lines))\n\tfor idx, line := range lines {\n\t\tvar obj map[string]any\n\t\tif json.Unmarshal(line, &obj) != nil {\n\t\t\tcontinue\n\t\t}\n\t\teventID := strings.ToUpper(strings.TrimSpace(strVal(obj["event_id"])))\n\t\tlogicalTimeStr := strVal(obj["logical_time"])\n\t\tif logicalTimeStr == "" {\n\t\t\tlogicalTimeStr = "1970-01-01T00:00:00Z"\n\t\t}\n\t\tt, err := time.Parse(time.RFC3339, logicalTimeStr)\n\t\tif err != nil {\n\t\t\tt = time.Unix(0, 0).UTC()\n\t\t}\n\t\tsortable = append(sortable, indexedEvent{time: t, eventID: eventID, lineIndex: idx, obj: obj})\n\t}\n\tsort.Slice(sortable, func(i, j int) bool {\n\t\ta, b := sortable[i], sortable[j]\n\t\tif !a.time.Equal(b.time) {\n\t\t\treturn a.time.Before(b.time)\n\t\t}\n\t\tif a.eventID != b.eventID {\n\t\t\treturn a.eventID < b.eventID\n\t\t}\n\t\treturn a.lineIndex < b.lineIndex\n\t})\n\tfor _, row := range sortable {\n\t\te.applyOne(row.obj, row.lineIndex)\n\t}\n}\n\nfunc (e *Engine) applyOne(obj map[string]any, lineIndex int) {\n\tev, rejection := validateEvent(obj, lineIndex)\n\tif rejection != nil {\n\t\te.Rejections = append(e.Rejections, *rejection)\n\t\te.RejectedCount++\n\t\tif rejection.EventID != "" {\n\t\t\te.RejectedIDs[rejection.EventID] = struct{}{}\n\t\t}\n\t\treturn\n\t}\n\tcanon := canonicalPayload(obj)\n\tif prev, ok := e.SeenEventIDs[ev.EventID]; ok {\n\t\tif !mapsEqual(prev, canon) {\n\t\t\te.reject(ev.EventID, ev.Principal, "duplicate_event_id")\n\t\t} else {\n\t\t\te.SkippedIdempotent++\n\t\t}\n\t\treturn\n\t}\n\te.SeenEventIDs[ev.EventID] = canon\n\n\tpsView := e.principalFor(ev.Principal)\n\tattemptLike := ev.Operation == "FAILED_ATTEMPT" || ev.Operation == "GRACE_HOLD" ||\n\t\tev.Operation == "CORRECTION_TALLY" || ev.Operation == "LOCKOUT_CLEAR"\n\tif attemptLike && psView != nil && psView.Suspended {\n\t\te.reject(ev.EventID, ev.Principal, "principal_suspended")\n\t\treturn\n\t}\n\n\tif ev.Operation == "ENFORCE_RESUME" {\n\t\tif psView == nil || !psView.Suspended {\n\t\t\te.reject(ev.EventID, ev.Principal, "principal_not_suspended")\n\t\t\treturn\n\t\t}\n\t\tif psView.SuspendedByReplica != "" && psView.SuspendedByReplica != ev.SourceReplica {\n\t\t\te.reject(ev.EventID, ev.Principal, "resume_replica_mismatch")\n\t\t\treturn\n\t\t}\n\t}\n\n\tsk := seqKey(ev.Principal, ev.SourceReplica)\n\tif prev := e.SeqHighwater[sk]; ev.Seq <= prev {\n\t\te.reject(ev.EventID, ev.Principal, "stale_seq")\n\t\treturn\n\t}\n\n\tif ev.Operation == "REVERT_ATTEMPT" {\n\t\tif psView != nil && psView.Suspended {\n\t\t\te.reject(ev.EventID, ev.Principal, "principal_suspended")\n\t\t\treturn\n\t\t}\n\t\tif ev.TargetEventID == ev.EventID {\n\t\t\te.reject(ev.EventID, ev.Principal, "revert_self")\n\t\t\treturn\n\t\t}\n\t\tif _, ok := e.Reversed[ev.TargetEventID]; ok {\n\t\t\te.reject(ev.EventID, ev.Principal, "revert_already_reversed")\n\t\t\treturn\n\t\t}\n\t\ttarget := e.Applied[ev.TargetEventID]\n\t\tif target == nil {\n\t\t\treason := "revert_target_missing"\n\t\t\tif _, ok := e.RejectedIDs[ev.TargetEventID]; ok {\n\t\t\t\treason = "revert_target_not_applied"\n\t\t\t}\n\t\t\te.reject(ev.EventID, ev.Principal, reason)\n\t\t\treturn\n\t\t}\n\t\tif target.SourceReplica != ev.SourceReplica {\n\t\t\te.reject(ev.EventID, ev.Principal, "revert_replica_mismatch")\n\t\t\treturn\n\t\t}\n\t\tif target.Principal != ev.Principal {\n\t\t\te.reject(ev.EventID, ev.Principal, "revert_cross_principal")\n\t\t\treturn\n\t\t}\n\t\tif target.Operation != "FAILED_ATTEMPT" {\n\t\t\te.reject(ev.EventID, ev.Principal, "revert_invalid_target")\n\t\t\treturn\n\t\t}\n\t}\n\n\tif ev.Operation == "GRACE_RELEASE" {\n\t\thold, ok := e.GraceExpires[ev.TargetEventID]\n\t\tif !ok || hold == "" {\n\t\t\te.reject(ev.EventID, ev.Principal, "grace_target_missing")\n\t\t\treturn\n\t\t}\n\t\ttarget := e.Applied[ev.TargetEventID]\n\t\tif target == nil || target.Operation != "GRACE_HOLD" {\n\t\t\te.reject(ev.EventID, ev.Principal, "grace_invalid_target")\n\t\t\treturn\n\t\t}\n\t\tif target.Principal != ev.Principal {\n\t\t\te.reject(ev.EventID, ev.Principal, "grace_invalid_target")\n\t\t\treturn\n\t\t}\n\t}\n\n\tps := e.ensurePrincipal(ev.Principal)\n\n\tswitch ev.Operation {\n\tcase "PRINCIPAL_BIND":\n\t\te.ActivePrincipal = ev.Principal\n\tcase "VIEW_ENTER":\n\t\te.ActiveView = ev.ViewID\n\tcase "FAILED_ATTEMPT":\n\t\tps.Failures++\n\t\te.recomputeLocked(ps)\n\tcase "LOCKOUT_CLEAR":\n\t\tps.Failures = 0\n\t\tps.Locked = false\n\tcase "GRACE_HOLD":\n\t\te.GraceExpires[ev.EventID] = ev.ExpiresAt\n\tcase "GRACE_RELEASE":\n\t\tdelete(e.GraceExpires, ev.TargetEventID)\n\tcase "REVERT_ATTEMPT":\n\t\tif ps.Failures > 0 {\n\t\t\tps.Failures--\n\t\t}\n\t\te.recomputeLocked(ps)\n\t\te.Reversed[ev.TargetEventID] = struct{}{}\n\tcase "CORRECTION_TALLY":\n\t\te.CorrectionPrev[ev.EventID] = ps.Failures\n\t\tps.Failures = *ev.Amount\n\t\te.recomputeLocked(ps)\n\tcase "ENFORCE_SUSPEND":\n\t\tps.Suspended = true\n\t\tps.SuspendedByReplica = ev.SourceReplica\n\tcase "ENFORCE_RESUME":\n\t\tps.Suspended = false\n\t\tps.SuspendedByReplica = ""\n\tcase "EPOCH_CARRY":\n\t\tdoubled := ps.Failures * 2\n\t\tif doubled > domain.MaxFailureCap {\n\t\t\tdoubled = domain.MaxFailureCap\n\t\t}\n\t\tps.Failures = doubled\n\t\te.recomputeLocked(ps)\n\t\tfor eid, holdPrincipal := range e.gracePrincipals() {\n\t\t\tif holdPrincipal == ev.Principal {\n\t\t\t\tdelete(e.GraceExpires, eid)\n\t\t\t}\n\t\t}\n\t\tps.Epoch = ev.Epoch\n\t}\n\n\tif ev.Principal != "" {\n\t\tps.LastEventID = ev.EventID\n\t\tps.LastLogicalTime = ev.LogicalTimeStr\n\t\tif ps.Epoch == 0 {\n\t\t\tps.Epoch = 1\n\t\t}\n\t}\n\tif ev.LogicalTime.After(e.MaxLogicalTime) {\n\t\te.MaxLogicalTime = ev.LogicalTime\n\t}\n\te.Applied[ev.EventID] = ev\n\te.SeqHighwater[sk] = ev.Seq\n\te.AppliedCount++\n\te.syncTally(ev.Principal)\n}\n\n// ApplyGraceExpirations converts expired GRACE_HOLD rows into failure strikes.\n// Watermark is max logical_time in the durable journal (or an explicit rebuild clock).\nfunc (e *Engine) ApplyGraceExpirations(now time.Time) {\n\ttype expRow struct {\n\t\teventID   string\n\t\texpires   time.Time\n\t\tprincipal string\n\t}\n\tvar rows []expRow\n\tfor eventID, expStr := range e.GraceExpires {\n\t\tif _, reversed := e.Reversed[eventID]; reversed {\n\t\t\tcontinue\n\t\t}\n\t\tev := e.Applied[eventID]\n\t\tif ev == nil || ev.Operation != "GRACE_HOLD" {\n\t\t\tcontinue\n\t\t}\n\t\texp, err := time.Parse(time.RFC3339, expStr)\n\t\tif err != nil {\n\t\t\tcontinue\n\t\t}\n\t\tif now.Before(exp) {\n\t\t\tcontinue\n\t\t}\n\t\trows = append(rows, expRow{eventID: eventID, expires: exp, principal: ev.Principal})\n\t}\n\tsort.Slice(rows, func(i, j int) bool {\n\t\tif rows[i].expires.Equal(rows[j].expires) {\n\t\t\treturn rows[i].eventID < rows[j].eventID\n\t\t}\n\t\treturn rows[i].expires.Before(rows[j].expires)\n\t})\n\tfor _, row := range rows {\n\t\tps := e.ensurePrincipal(row.principal)\n\t\tps.Failures++\n\t\te.recomputeLocked(ps)\n\t\te.syncTally(row.principal)\n\t\tdelete(e.GraceExpires, row.eventID)\n\t}\n}\n\nfunc (e *Engine) Watermark() time.Time {\n\treturn e.MaxLogicalTime\n}\n\nfunc (e *Engine) PersistTallies() error {\n\tfor principal, ps := range e.Principals {\n\t\tif err := state.WriteAuthTally(principal, ps.Failures, ps.Locked); err != nil {\n\t\t\treturn err\n\t\t}\n\t\te.Tallies[principal] = &domain.Tally{\n\t\t\tPrincipal: principal,\n\t\t\tFailures:  ps.Failures,\n\t\t\tLocked:    ps.Locked,\n\t\t}\n\t}\n\treturn nil\n}\n\nfunc (e *Engine) SeedTally(principal string, failures int, locked bool) {\n\tps := e.ensurePrincipal(principal)\n\tps.Failures = failures\n\tps.Locked = locked || failures >= domain.FailureLimit\n\tps.LastEventID = "LEGACY-IMPORT"\n\tps.LastLogicalTime = "1970-01-01T00:00:00Z"\n\te.syncTally(principal)\n}\n\nfunc (e *Engine) gracePrincipals() map[string]string {\n\tout := map[string]string{}\n\tfor eid := range e.GraceExpires {\n\t\tif ev := e.Applied[eid]; ev != nil {\n\t\t\tout[eid] = ev.Principal\n\t\t}\n\t}\n\treturn out\n}\n\nfunc (e *Engine) principalFor(principal string) *PrincipalState {\n\tif principal == "" {\n\t\treturn nil\n\t}\n\treturn e.Principals[principal]\n}\n\nfunc (e *Engine) ensurePrincipal(principal string) *PrincipalState {\n\tif principal == "" {\n\t\treturn &PrincipalState{}\n\t}\n\tif ps, ok := e.Principals[principal]; ok {\n\t\treturn ps\n\t}\n\tps := &PrincipalState{Principal: principal, Epoch: 1}\n\te.Principals[principal] = ps\n\treturn ps\n}\n\nfunc (e *Engine) recomputeLocked(ps *PrincipalState) {\n\tps.Locked = ps.Failures >= domain.FailureLimit\n}\n\nfunc (e *Engine) syncTally(principal string) {\n\tif principal == "" {\n\t\treturn\n\t}\n\tps := e.Principals[principal]\n\tif ps == nil {\n\t\treturn\n\t}\n\te.Tallies[principal] = &domain.Tally{\n\t\tPrincipal: principal,\n\t\tFailures:  ps.Failures,\n\t\tLocked:    ps.Locked,\n\t}\n}\n\nfunc (e *Engine) reject(eventID, principal, reason string) {\n\te.Rejections = append(e.Rejections, domain.Rejection{\n\t\tEventID:      eventID,\n\t\tPrincipal:    principal,\n\t\tReason:       reason,\n\t\tPriorityRank: domain.RejectionRanks[reason],\n\t})\n\te.RejectedCount++\n\tif eventID != "" {\n\t\te.RejectedIDs[eventID] = struct{}{}\n\t}\n}\n\nfunc validateEvent(obj map[string]any, lineIndex int) (*Event, *domain.Rejection) {\n\trequired := []string{"event_id", "operation", "logical_time", "seq", "source_replica"}\n\tfor _, key := range required {\n\t\tif _, ok := obj[key]; !ok {\n\t\t\treturn nil, &domain.Rejection{Reason: "missing_required", PriorityRank: domain.RejectionRanks["missing_required"]}\n\t\t}\n\t}\n\teventID, _ := obj["event_id"].(string)\n\tnormID := strings.ToUpper(strings.TrimSpace(eventID))\n\tif !domain.EventIDRe.MatchString(normID) {\n\t\treturn nil, &domain.Rejection{EventID: eventID, Reason: "invalid_event_id", PriorityRank: domain.RejectionRanks["invalid_event_id"]}\n\t}\n\top, _ := obj["operation"].(string)\n\top = strings.ToUpper(strings.TrimSpace(op))\n\tif _, ok := domain.AllowedOps[op]; !ok {\n\t\treturn nil, &domain.Rejection{EventID: eventID, Reason: "invalid_operation", PriorityRank: domain.RejectionRanks["invalid_operation"]}\n\t}\n\treplica, _ := obj["source_replica"].(string)\n\tif !domain.ReplicaRe.MatchString(strings.ToUpper(strings.TrimSpace(replica))) {\n\t\treturn nil, &domain.Rejection{EventID: eventID, Reason: "invalid_replica", PriorityRank: domain.RejectionRanks["invalid_replica"]}\n\t}\n\tseqF, ok := obj["seq"].(float64)\n\tif !ok || int(seqF) < 1 {\n\t\treturn nil, &domain.Rejection{EventID: eventID, Reason: "invalid_seq", PriorityRank: domain.RejectionRanks["invalid_seq"]}\n\t}\n\tltStr, _ := obj["logical_time"].(string)\n\tlt, err := time.Parse(time.RFC3339, ltStr)\n\tif err != nil {\n\t\treturn nil, &domain.Rejection{EventID: eventID, Reason: "invalid_logical_time", PriorityRank: domain.RejectionRanks["invalid_logical_time"]}\n\t}\n\tprincipal := ""\n\tif raw, ok := obj["principal"]; ok {\n\t\tprincipal, _ = raw.(string)\n\t}\n\tviewID := domain.ViewHost\n\tif raw, ok := obj["view_id"]; ok {\n\t\tviewID, _ = raw.(string)\n\t}\n\tneedsPrincipal := map[string]bool{\n\t\t"FAILED_ATTEMPT": true, "LOCKOUT_CLEAR": true, "PRINCIPAL_BIND": true,\n\t\t"GRACE_HOLD": true, "GRACE_RELEASE": true, "REVERT_ATTEMPT": true,\n\t\t"CORRECTION_TALLY": true, "ENFORCE_SUSPEND": true, "ENFORCE_RESUME": true, "EPOCH_CARRY": true,\n\t}\n\tif needsPrincipal[op] {\n\t\tif principal == "" || !domain.PrincipalRe.MatchString(principal) {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_principal", PriorityRank: domain.RejectionRanks["invalid_principal"]}\n\t\t}\n\t}\n\tif op == "VIEW_ENTER" || op == "FAILED_ATTEMPT" {\n\t\tviewID = strings.TrimSpace(viewID)\n\t\tif viewID != domain.ViewHost && viewID != domain.ViewNS {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Reason: "invalid_view_id", PriorityRank: domain.RejectionRanks["invalid_view_id"]}\n\t\t}\n\t}\n\tev := &Event{\n\t\tEventID:        normID,\n\t\tPrincipal:      principal,\n\t\tOperation:      op,\n\t\tViewID:         viewID,\n\t\tLogicalTime:    lt,\n\t\tLogicalTimeStr: ltStr,\n\t\tSeq:            int(seqF),\n\t\tSourceReplica:  strings.ToUpper(strings.TrimSpace(replica)),\n\t\tLineIndex:      lineIndex,\n\t}\n\tif op == "GRACE_HOLD" {\n\t\texp, _ := obj["expires_at"].(string)\n\t\tif exp == "" {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_expires_at", PriorityRank: domain.RejectionRanks["invalid_expires_at"]}\n\t\t}\n\t\tif _, err := time.Parse(time.RFC3339, exp); err != nil {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_expires_at", PriorityRank: domain.RejectionRanks["invalid_expires_at"]}\n\t\t}\n\t\tev.ExpiresAt = exp\n\t}\n\tif op == "GRACE_RELEASE" || op == "REVERT_ATTEMPT" {\n\t\traw, ok := obj["target_event_id"]\n\t\tif !ok || raw == nil {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "missing_target", PriorityRank: domain.RejectionRanks["missing_target"]}\n\t\t}\n\t\ttid, _ := raw.(string)\n\t\ttid = strings.ToUpper(strings.TrimSpace(tid))\n\t\tif !domain.EventIDRe.MatchString(tid) {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_target", PriorityRank: domain.RejectionRanks["invalid_target"]}\n\t\t}\n\t\tev.TargetEventID = tid\n\t}\n\tif op == "CORRECTION_TALLY" {\n\t\tamtRaw, ok := obj["amount"]\n\t\tif !ok {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_amount", PriorityRank: domain.RejectionRanks["invalid_amount"]}\n\t\t}\n\t\tamtF, ok := amtRaw.(float64)\n\t\tif !ok || amtF < 0 {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_amount", PriorityRank: domain.RejectionRanks["invalid_amount"]}\n\t\t}\n\t\tamt := int(amtF)\n\t\tev.Amount = &amt\n\t}\n\tif op == "EPOCH_CARRY" {\n\t\tepRaw, ok := obj["epoch"]\n\t\tif !ok {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_epoch", PriorityRank: domain.RejectionRanks["invalid_epoch"]}\n\t\t}\n\t\tepF, ok := epRaw.(float64)\n\t\tif !ok || int(epF) < 1 {\n\t\t\treturn nil, &domain.Rejection{EventID: eventID, Principal: principal, Reason: "invalid_epoch", PriorityRank: domain.RejectionRanks["invalid_epoch"]}\n\t\t}\n\t\tev.Epoch = int(epF)\n\t}\n\treturn ev, nil\n}\n\nfunc canonicalPayload(obj map[string]any) map[string]any {\n\tout := map[string]any{}\n\tfor k, v := range obj {\n\t\tswitch k {\n\t\tcase "event_id", "source_replica", "target_event_id":\n\t\t\ts, _ := v.(string)\n\t\t\tout[k] = strings.ToUpper(strings.TrimSpace(s))\n\t\tcase "operation":\n\t\t\ts, _ := v.(string)\n\t\t\tout[k] = strings.ToUpper(strings.TrimSpace(s))\n\t\tcase "principal", "view_id", "expires_at":\n\t\t\ts, _ := v.(string)\n\t\t\tout[k] = strings.TrimSpace(s)\n\t\tdefault:\n\t\t\tout[k] = v\n\t\t}\n\t}\n\treturn out\n}\n\nfunc mapsEqual(a, b map[string]any) bool {\n\taj, _ := json.Marshal(a)\n\tbj, _ := json.Marshal(b)\n\treturn string(aj) == string(bj)\n}\n\nfunc strVal(v any) string {\n\ts, _ := v.(string)\n\treturn s\n}\n\n// SortEvents returns durable lines ordered for replay (shared helper for tests/tools).\nfunc SortEvents(lines [][]byte) [][]byte {\n\ttype item struct {\n\t\tline []byte\n\t\tidx  int\n\t\tev   *Event\n\t}\n\titems := []item{}\n\tfor idx, line := range lines {\n\t\tvar obj map[string]any\n\t\tif json.Unmarshal(line, &obj) != nil {\n\t\t\tcontinue\n\t\t}\n\t\tev, rej := validateEvent(obj, idx)\n\t\tif rej != nil {\n\t\t\titems = append(items, item{line: line, idx: idx, ev: &Event{\n\t\t\t\tEventID:     strings.ToUpper(strings.TrimSpace(strVal(obj["event_id"]))),\n\t\t\t\tLogicalTime: time.Unix(0, 0).UTC(),\n\t\t\t\tLineIndex:   idx,\n\t\t\t}})\n\t\t\tcontinue\n\t\t}\n\t\titems = append(items, item{line: line, idx: idx, ev: ev})\n\t}\n\tsort.Slice(items, func(i, j int) bool {\n\t\ta, b := items[i].ev, items[j].ev\n\t\tif !a.LogicalTime.Equal(b.LogicalTime) {\n\t\t\treturn a.LogicalTime.Before(b.LogicalTime)\n\t\t}\n\t\tif a.EventID != b.EventID {\n\t\t\treturn a.EventID < b.EventID\n\t\t}\n\t\treturn a.LineIndex < b.LineIndex\n\t})\n\tout := make([][]byte, len(items))\n\tfor i, it := range items {\n\t\tout[i] = it.line\n\t}\n\treturn out\n}\n')
