igest,\n\t\ttrail.ProjectionDigest,\n\t\ttrail.Batches,\n\t)\n\tif err != nil {\n\t\treturn err\n\t}\n\ttrail.AuditDigest = digest\n\tdata, err := json.MarshalIndent(trail, "", "  ")\n\tif err != nil {\n\t\treturn err\n\t}\n\tdata = append(data, \'\\n\')\n\tif err := os.MkdirAll(config.OutputDir, 0o755); err != nil {\n\t\treturn err\n\t}\n\treturn os.WriteFile(path, data, 0o644)\n}\n')
