Path('/app/internal/ops/u_clear.go').write_text('package ops\n\nimport (\n\t"baylock/internal/domain"\n\t"baylock/internal/state"\n)\n\n// SelectStore resolves the authoritative backend for counter mutations.\nfunc SelectStore(viewID, principal string) string {\n\treturn state.NsPathFor(viewID, principal)\n}\n\nfunc ClearPrincipalCounters(principal string) error {\n\ttally := &domain.Tally{Principal: principal, Failures: 0, Locked: false}\n\tif err := state.SaveTally(state.AuthPath(principal), tally); err != nil {\n\t\treturn err\n\t}\n\treturn state.SyncShadows(principal, tally)\n}\n\nfunc PurgeCounters(viewID, principal string) (bool, error) {\n\tpath := SelectStore(viewID, principal)\n\ttally := &domain.Tally{Principal: principal, Failures: 0, Locked: false}\n\tif err := state.SaveTally(path, tally); err != nil {\n\t\treturn false, err\n\t}\n\tif err := state.SyncShadows(principal, tally); err != nil {\n\t\treturn false, err\n\t}\n\tif path != state.AuthPath(principal) {\n\t\tif err := ClearPrincipalCounters(principal); err != nil {\n\t\t\treturn false, err\n\t\t}\n\t}\n\treturn true, nil\n}\n\nfunc UnlockRequest(viewID, principal string) (bool, error) {\n\tok, err := PurgeCounters(viewID, principal)\n\tif err != nil {\n\t\treturn false, err\n\t}\n\tif !ok {\n\t\treturn false, nil\n\t}\n\treturn ClearPrincipalCounters(principal) == nil, nil\n}\n')
