Path('/app/internal/ns/n_coord.go').write_text('package ns\n\nimport (\n\t"baylock/internal/domain"\n\t"baylock/internal/state"\n)\n\nfunc EnterView(rt *domain.Runtime, viewID string) {\n\tif !ValidateViewID(viewID) {\n\t\tviewID = domain.ViewHost\n\t}\n\trt.ActiveView = viewID\n\tReconcileViews(rt)\n}\n\nfunc ReconcileViews(rt *domain.Runtime) {\n\tif rt == nil || rt.Principal == "" {\n\t\treturn\n\t}\n\ttally, err := state.LoadAuthTally(rt.Principal)\n\tif err != nil || tally == nil {\n\t\treturn\n\t}\n\tcloned := state.CloneTally(tally)\n\tcloned.Principal = rt.Principal\n\t_ = state.SyncShadows(rt.Principal, cloned)\n}\n\nfunc SyncActiveView(rt *domain.Runtime, viewID string) {\n\tif !ValidateViewID(viewID) {\n\t\treturn\n\t}\n\trt.ActiveView = viewID\n\tReconcileViews(rt)\n}\n\nfunc ActiveView(rt *domain.Runtime) string {\n\tif rt.ActiveView == "" {\n\t\treturn domain.ViewHost\n\t}\n\treturn rt.ActiveView\n}\n\nfunc ValidateViewID(viewID string) bool {\n\treturn viewID == domain.ViewHost || viewID == domain.ViewNS\n}\n')
