Path('/app/internal/report/r_emit.go').write_text('package report\n\nimport (\n\t"encoding/json"\n\t"sort"\n\n\t"baylock/internal/app"\n\t"baylock/internal/codec"\n\t"baylock/internal/domain"\n\t"baylock/internal/projection"\n\t"baylock/internal/state"\n)\n\nfunc WriteLedger(path string) error {\n\trt, err := app.LoadRuntime()\n\tif err != nil {\n\t\treturn err\n\t}\n\tsnap, err := projection.Load()\n\tif err != nil {\n\t\tsnap = &projection.Snapshot{GeneratedFrom: domain.GeneratedFrom}\n\t}\n\tledger := BuildLedger(rt, snap)\n\tdigest, err := ledgerDigest(ledger)\n\tif err != nil {\n\t\treturn err\n\t}\n\tledger.LedgerDigest = digest\n\tdata, err := json.MarshalIndent(ledger, "", "  ")\n\tif err != nil {\n\t\treturn err\n\t}\n\tdata = append(data, \'\\n\')\n\treturn app.WriteFile(path, data)\n}\n\nfunc collectViews(rt *domain.Runtime) []domain.ViewState {\n\tviews := []domain.ViewState{}\n\tif rt.Principal == "" {\n\t\treturn views\n\t}\n\tfor _, viewID := range []string{domain.ViewHost, domain.ViewNS} {\n\t\tview, err := state.ReadViewState(viewID, rt.Principal)\n\t\tif err != nil || view == nil {\n\t\t\tcontinue\n\t\t}\n\t\tviews = append(views, *view)\n\t}\n\treturn views\n}\n\nfunc failureFromAuth(rt *domain.Runtime) int {\n\tif rt.Principal == "" {\n\t\treturn 0\n\t}\n\tauth, err := state.LoadAuthTally(rt.Principal)\n\tif err != nil || auth == nil {\n\t\treturn 0\n\t}\n\treturn auth.Failures\n}\n\nfunc BuildLedger(rt *domain.Runtime, snap *projection.Snapshot) domain.Ledger {\n\tviews := collectViews(rt)\n\taudits := append([]domain.AuditRecord{}, rt.Audits...)\n\tsort.Slice(audits, func(i, j int) bool {\n\t\tif audits[i].Seq == audits[j].Seq {\n\t\t\treturn audits[i].ViewID < audits[j].ViewID\n\t\t}\n\t\treturn audits[i].Seq < audits[j].Seq\n\t})\n\tsort.Slice(views, func(i, j int) bool {\n\t\tif views[i].ViewID == views[j].ViewID {\n\t\t\treturn views[i].Principal < views[j].Principal\n\t\t}\n\t\treturn views[i].ViewID < views[j].ViewID\n\t})\n\tif snap == nil {\n\t\tsnap = &projection.Snapshot{GeneratedFrom: domain.GeneratedFrom}\n\t}\n\treturn domain.Ledger{\n\t\tGeneratedFrom:    domain.GeneratedFrom,\n\t\tAttemptCount:     rt.AttemptCount,\n\t\tFailureTotal:     failureFromAuth(rt),\n\t\tEventLineCount:   snap.EventLineCount,\n\t\tAppliedCount:     snap.AppliedCount,\n\t\tRejectedCount:    snap.RejectedCount,\n\t\tProjectionDigest: snap.ProjectionDigest,\n\t\tViews:            views,\n\t\tAudits:           audits,\n\t}\n}\n\nfunc ledgerDigest(ledger domain.Ledger) (string, error) {\n\tviewMaps := make([]map[string]any, 0, len(ledger.Views))\n\tfor _, view := range ledger.Views {\n\t\tviewMaps = append(viewMaps, map[string]any{\n\t\t\t"view_id":       view.ViewID,\n\t\t\t"principal":     view.Principal,\n\t\t\t"failure_count": view.FailureCount,\n\t\t\t"locked":        view.Locked,\n\t\t})\n\t}\n\tauditMaps := make([]map[string]any, 0, len(ledger.Audits))\n\tfor _, audit := range ledger.Audits {\n\t\tauditMaps = append(auditMaps, map[string]any{\n\t\t\t"view_id":   audit.ViewID,\n\t\t\t"principal": audit.Principal,\n\t\t\t"actor_ref": audit.ActorRef,\n\t\t\t"seq":       audit.Seq,\n\t\t})\n\t}\n\treturn codec.LockDigestBody(\n\t\tledger.GeneratedFrom,\n\t\tledger.AttemptCount,\n\t\tledger.FailureTotal,\n\t\tledger.EventLineCount,\n\t\tledger.AppliedCount,\n\t\tledger.RejectedCount,\n\t\tledger.ProjectionDigest,\n\t\tviewMaps,\n\t\tauditMaps,\n\t)\n}\n')
